1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	} as const satisfies Record<string, number>;
52	
53	type KnownItemType = keyof typeof BASE_PREMIUMS;
54	
55	const basePremiumOf = (itemType: string): number => BASE_PREMIUMS[itemType as KnownItemType];
56	
57	const BLOCK_SIZE = 3;
58	const BLOCK_PREMIUM = 60;
59	
60	const countsByType = (items: Item[]): Map<string, number> => {
61	  const counts = new Map<string, number>();
62	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
63	  return counts;
64	};
65	
66	const basePremiumForGroup = (itemType: string, count: number): number => {
67	  if (count === BLOCK_SIZE) return BLOCK_PREMIUM;
68	  return count * basePremiumOf(itemType);
69	};
70	
71	const policyBasePremiumOf = (items: Item[]): number =>
72	  [...countsByType(items)].reduce(
73	    (total, [itemType, count]) => total + basePremiumForGroup(itemType, count),
74	    0,
75	  );
76	
77	const CURSE_SURCHARGE = 0.5;
78	
79	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
80	const HIGH_ENCHANTMENT_THRESHOLD = 5;
81	
82	const itemSurchargeRateOf = (item: Item): number => {
83	  const curse = item.cursed ? CURSE_SURCHARGE : 0;
84	  const enchantment =
85	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE : 0;
86	  return curse + enchantment;
87	};
88	
89	const itemSurchargesOf = (items: Item[]): number =>
90	  items.reduce((total, item) => total + basePremiumOf(item.type) * itemSurchargeRateOf(item), 0);
91	
92	const LOYALTY_DISCOUNT = 0.2;
93	const LOYALTY_THRESHOLD_YEARS = 2;
94	
95	const loyaltyRateOf = (customer: Customer): number =>
96	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? -LOYALTY_DISCOUNT : 0;
97	
98	const FOLLOW_UP_DISCOUNT = 0.15;
99	
100	// `contractOrdinal` is zero-based: the customer's first contract in the
101	// scenario is 0 and carries no follow-up discount.
102	const followUpRateOf = (contractOrdinal: number): number =>
103	  contractOrdinal > 0 ? -FOLLOW_UP_DISCOUNT : 0;
104	
105	// The policy-scoped rate is the sum of every modifier that scales the policy
106	// base premium. Each addend names one rule from the spec.
107	const policyModifierRateOf = (customer: Customer, contractOrdinal: number): number =>
108	  FIRST_INSURANCE_SURCHARGE + loyaltyRateOf(customer) + followUpRateOf(contractOrdinal);
109	
110	const premiumFor = (quote: QuoteStep, customer: Customer, contractOrdinal: number): number => {
111	  const policyBase = policyBasePremiumOf(quote.items);
112	  // Policy-scoped modifiers apply to the policy base only; item-scoped
113	  // surcharges are added afterwards and never widen that base.
114	  const policyModifiers = policyBase * policyModifierRateOf(customer, contractOrdinal);
115	  return Math.ceil(
116	    policyBase + itemSurchargesOf(quote.items) + policyModifiers + PROCESSING_FEE,
117	  );
118	};
119	
120	const INSURANCE_VALUES = {
121	  sword: 1000,
122	  amulet: 600,
123	  staff: 800,
124	  potion: 400,
125	  rune: 250,
126	  moonstone: 250,
127	} as const satisfies Record<string, number>;
128	
129	const insuranceValueOf = (itemType: string): number =>
130	  INSURANCE_VALUES[itemType as KnownItemType];
131	
132	const DEDUCTIBLE = 100;
133	const CAP_MULTIPLE = 2;
134	
135	interface Policy {
136	  items: Item[];
137	  remainingCap: number;
138	}
139	
140	const openPolicy = (items: Item[]): Policy => {
141	  const insuranceSum = items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
142	  return { items, remainingCap: insuranceSum * CAP_MULTIPLE };
143	};
144	
145	const payoutForDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;
146	
147	const settle = (claim: ClaimStep, policy: Policy): StepResult => {
148	  const payout = claim.incident.damages.reduce(
149	    (total, damage) => total + payoutForDamage(damage),
150	    0,
151	  );
152	  policy.remainingCap -= payout;
153	  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
154	};
155	
156	export const runScenario = (scenario: Scenario): ScenarioResult => {
157	  // Counts the quote steps seen so far. Only quotes open a contract, so this
158	  // deliberately tracks the customer's contracts rather than the step index —
159	  // a claim step between two quotes must not advance the ordinal.
160	  let contractsSoFar = 0;
161	  const policies = new Map<number, Policy>();
162	
163	  const resultOf = (step: Step, index: number): StepResult => {
164	    if (step.op === "claim") {
165	      const policy = policies.get(step.policy)!;
166	      return settle(step, policy);
167	    }
168	    const premium = premiumFor(step, scenario.customer, contractsSoFar);
169	    contractsSoFar += 1;
170	    policies.set(index, openPolicy(step.items));
171	    return { premium };
172	  };
173	
174	  return { results: scenario.steps.map(resultOf) };
175	};
