// The deductible is withheld once per damage entry, not once per claim.
const afterDeductible = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const settle = (claim: ClaimStep, policy: Policy): StepResult => {
  const payout = claim.incident.damages.reduce(
    (total, damage) => total + afterDeductible(damage),
    0,
  );

export type QuoteResult = { premium: number };
export type ClaimResult = { payout: number; remainingCap: number };
export type StepResult = QuoteResult | ClaimResult;
